'use strict';
document.documentElement.classList.add('js');
const one = (selector) => document.querySelector(selector);
const storage = {
get(key) { try { return localStorage.getItem(key); } catch { return null; } },
set(key, value) { try { localStorage.setItem(key, value); return true; } catch { return false; } },
remove(key) { try { localStorage.removeItem(key); } catch { /* Sin datos persistentes que eliminar. */ } }
};
const themeButton = one('#theme-toggle');
const savedTheme = storage.get('pulso-theme');
if (savedTheme === 'dark' || savedTheme === 'light') document.documentElement.dataset.theme = savedTheme;
function syncTheme() {
const dark = document.documentElement.dataset.theme === 'dark' || (!document.documentElement.dataset.theme && matchMedia('(prefers-color-scheme: dark)').matches);
themeButton?.setAttribute('aria-pressed', String(dark));
}
syncTheme();
themeButton?.addEventListener('click', () => {
const next = themeButton.getAttribute('aria-pressed') === 'true' ? 'light' : 'dark';
document.documentElement.dataset.theme = next;
storage.set('pulso-theme', next);
syncTheme();
});
function menu(buttonId, menuId, breakpoint) {
const button = one(buttonId), panel = one(menuId);
if (!button || !panel) return;
const media = matchMedia(`(min-width: ${breakpoint}px)`);
const setOpen = (open) => { panel.hidden = !open; button.setAttribute('aria-expanded', String(open)); };
const resize = () => setOpen(media.matches);
resize();
media.addEventListener('change', resize);
button.addEventListener('click', () => setOpen(panel.hidden));
document.addEventListener('keydown', (event) => {
if (event.key === 'Escape' && !media.matches && !panel.hidden) { setOpen(false); button.focus(); }
});
}
menu('#menu-toggle', '#main-menu', 768);
menu('#admin-toggle', '#admin-menu', 1024);
one('#errors')?.focus();
let dialogTrigger = null;
document.querySelectorAll('[data-close-dialog]').forEach((button) => button.addEventListener('click', () => button.closest('dialog').close()));
document.querySelectorAll('dialog').forEach((dialog) => dialog.addEventListener('close', () => dialogTrigger?.focus()));
const confirmation = one('#confirm-dialog');
let pendingForm = null;
document.querySelectorAll('form[data-confirm]').forEach((form) => {
const checkbox = form.querySelector('[name="confirm"]');
checkbox.required = false;
checkbox.closest('label').hidden = true;
form.addEventListener('submit', (event) => {
event.preventDefault();
pendingForm = form;
dialogTrigger = event.submitter;
confirmation.showModal();
confirmation.querySelector('[data-close-dialog]').focus();
});
});
one('#confirm-submit')?.addEventListener('click', () => {
if (pendingForm) { pendingForm.querySelector('[name="confirm"]').checked = true; pendingForm.submit(); }
});
one('#reading-toggle')?.addEventListener('click', (event) => {
const enabled = document.body.classList.toggle('reading');
event.currentTarget.setAttribute('aria-pressed', String(enabled));
event.currentTarget.textContent = enabled ? 'Salir del modo de lectura' : 'Modo de lectura';
});
const editor = one('#article-form');
if (editor) {
const key = `pulso-draft-${editor.dataset.draftKey}-${location.pathname}`;
const status = one('#draft-status'), restore = one('#draft-restore'), discard = one('#draft-discard');
if (editor.dataset.saved === '1') storage.remove(key);
let draft;
try { draft = JSON.parse(storage.get(key)); } catch { draft = null; }
if (draft) {
status.textContent = 'Hay un borrador local disponible. Recuperarlo no cambia la versión guardada en el servidor.';
restore.hidden = false; discard.hidden = false;
}
const controls = [...editor.elements].filter((field) => field.name && !['csrf', 'updated_at', 'image'].includes(field.name));
restore.addEventListener('click', () => {
controls.forEach((field) => {
const value = draft[field.name];
if (value === undefined) return;
if (field.type === 'checkbox') field.checked = Array.isArray(value) && value.includes(field.value);
else field.value = value;
});
status.textContent = 'Borrador recuperado. Revisa el contenido antes de guardarlo en el servidor.';
restore.hidden = true;
});
discard.addEventListener('click', () => {
storage.remove(key); draft = null; restore.hidden = true; discard.hidden = true; status.textContent = 'Borrador local descartado.';
});
let timer;
editor.addEventListener('input', () => {
clearTimeout(timer);
timer = setTimeout(() => {
const values = {};
controls.forEach((field) => {
if (field.type === 'checkbox') { values[field.name] ??= []; if (field.checked) values[field.name].push(field.value); }
else values[field.name] = field.value;
});
const saved = storage.set(key, JSON.stringify(values));
status.textContent = saved ? 'Borrador guardado en este navegador. Aún no se ha enviado al servidor.' : 'No se pudo guardar el borrador local. Guarda la noticia o copia el texto antes de salir.';
}, 600);
});
}
document.querySelectorAll('form:not([data-confirm])').forEach((form) => form.addEventListener('submit', () => {
if (!form.checkValidity()) return;
const message = one('#save-status');
if (message) message.textContent = 'Guardando… espera la confirmación.';
form.setAttribute('aria-busy', 'true');
}));
const sessionSeconds = Number(document.body.dataset.sessionSeconds);
if (sessionSeconds) {
const sessionDialog = one('#session-dialog');
let sessionTimer;
const schedule = () => { sessionTimer = setTimeout(() => {
dialogTrigger = document.activeElement;
if (!sessionDialog.open) sessionDialog.showModal();
}, Math.max(1, sessionSeconds - 60) * 1000); };
schedule();
sessionDialog.querySelector('form').addEventListener('submit', async (event) => {
event.preventDefault();
const form = event.currentTarget;
try {
const response = await fetch(form.action, { method: 'POST', body: new FormData(form), headers: { Accept: 'application/json' } });
if (!response.ok || !(await response.json()).extended) throw new Error('expired');
one('#session-status').textContent = 'Sesión extendida. Tus datos siguen en el formulario.';
form.removeAttribute('aria-busy');
clearTimeout(sessionTimer); schedule();
sessionDialog.close();
} catch {
one('#session-status').textContent = 'No se pudo extender la sesión. Copia tus datos y vuelve a iniciar sesión.';
form.removeAttribute('aria-busy');
}
});
}